package checkpoint

import (
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"

	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// ReadCommitted reads the checkpoint summary from the v2 /main ref.
// Returns nil, nil if the checkpoint doesn't exist (same contract as GitStore.ReadCommitted).
func (s *V2GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
	if err := ctx.Err(); err != nil {
		return nil, err //nolint:wrapcheck // Propagating context cancellation
	}

	refName := plumbing.ReferenceName(paths.V2MainRefName)
	_, rootTreeHash, err := s.GetRefState(refName)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Ref doesn't exist means no checkpoint
	}

	rootTree, err := s.repo.TreeObject(rootTreeHash)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Tree not readable
	}

	cpTree, err := rootTree.Tree(checkpointID.Path())
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Checkpoint subtree not found
	}

	cpFT := s.wrapWithFetcher(ctx, cpTree)
	metadataFile, err := cpFT.File(paths.MetadataFileName)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // metadata.json not found
	}

	content, err := metadataFile.Contents()
	if err != nil {
		return nil, fmt.Errorf("failed to read metadata.json: %w", err)
	}

	var summary CheckpointSummary
	if err := json.Unmarshal([]byte(content), &summary); err != nil {
		return nil, fmt.Errorf("failed to parse metadata.json: %w", err)
	}

	return &summary, nil
}

// ListCommitted lists all committed checkpoints from the v2 /main ref.
// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
func (s *V2GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
	if err := ctx.Err(); err != nil {
		return nil, err //nolint:wrapcheck // Propagating context cancellation
	}

	refName := plumbing.ReferenceName(paths.V2MainRefName)
	_, rootTreeHash, err := s.GetRefState(refName)
	if err != nil {
		return []CommittedInfo{}, nil //nolint:nilerr // No /main ref means empty list
	}

	rootTree, err := s.repo.TreeObject(rootTreeHash)
	if err != nil {
		return []CommittedInfo{}, nil //nolint:nilerr // Unreadable tree means no listable entries
	}

	var checkpoints []CommittedInfo

	_ = WalkCheckpointShards(ctx, s.repo, rootTree, func(checkpointID id.CheckpointID, cpTreeHash plumbing.Hash) error { //nolint:errcheck // callback never returns errors
		checkpointTree, cpTreeErr := s.repo.TreeObject(cpTreeHash)
		if cpTreeErr != nil {
			logging.Debug(ctx, "v2 ListCommitted: skipping unreadable checkpoint tree",
				slog.String("checkpoint_id", checkpointID.String()),
				slog.String("error", cpTreeErr.Error()))
			return nil
		}

		checkpoints = append(checkpoints, readCommittedInfoFromCheckpointTree(checkpointID, checkpointTree))
		return nil
	})

	sort.Slice(checkpoints, func(i, j int) bool {
		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
	})

	return checkpoints, nil
}

// ReadSessionCompactTranscript reads transcript.jsonl for a session from the v2
// /main ref. Returns ErrNoTranscript when compact transcript is missing.
func (s *V2GitStore) ReadSessionCompactTranscript(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) ([]byte, error) {
	if err := ctx.Err(); err != nil {
		return nil, err //nolint:wrapcheck // Propagating context cancellation
	}

	refName := plumbing.ReferenceName(paths.V2MainRefName)
	_, rootTreeHash, err := s.GetRefState(refName)
	if err != nil {
		return nil, ErrCheckpointNotFound
	}

	rootTree, err := s.repo.TreeObject(rootTreeHash)
	if err != nil {
		return nil, ErrCheckpointNotFound
	}

	cpTree, err := rootTree.Tree(checkpointID.Path())
	if err != nil {
		return nil, ErrCheckpointNotFound
	}

	sessionDir := strconv.Itoa(sessionIndex)
	sessionTree, err := cpTree.Tree(sessionDir)
	if err != nil {
		return nil, ErrCheckpointNotFound
	}

	sessionFT := s.wrapWithFetcher(ctx, sessionTree)
	compactFile, err := sessionFT.File(paths.CompactTranscriptFileName)
	if err != nil {
		return nil, ErrNoTranscript
	}

	content, err := compactFile.Contents()
	if err != nil {
		return nil, ErrNoTranscript
	}
	if content == "" {
		return nil, ErrNoTranscript
	}

	return []byte(content), nil
}

// ReadSessionMetadata reads only the session's metadata.json from the v2
// /main ref — cheaper than ReadSessionMetadataAndPrompts when the caller
// only needs metadata fields (e.g. SessionID, Kind, Agent). Lazy-fetches
// the metadata blob via wrapWithFetcher when missing locally. Returns
// ErrCheckpointNotFound if the checkpoint or session doesn't exist on /main.
func (s *V2GitStore) ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*CommittedMetadata, error) {
	if err := ctx.Err(); err != nil {
		return nil, err //nolint:wrapcheck // Propagating context cancellation
	}

	refName := plumbing.ReferenceName(paths.V2MainRefName)
	_, rootTreeHash, err := s.GetRefState(refName)
	if err != nil {
		return nil, ErrCheckpointNotFound
	}

	rootTree, err := s.repo.TreeObject(rootTreeHash)
	if err != nil {
		return nil, ErrCheckpointNotFound
	}

	cpTree, err := rootTree.Tree(checkpointID.Path())
	if err != nil {
		return nil, ErrCheckpointNotFound
	}

	sessionTree, err := cpTree.Tree(strconv.Itoa(sessionIndex))
	if err != nil {
		return nil, ErrCheckpointNotFound
	}

	sessionFT := s.wrapWithFetcher(ctx, sessionTree)
	metadataFile, err := sessionFT.File(paths.MetadataFileName)
	if err != nil {
		return nil, fmt.Errorf("read session metadata file: %w", err)
	}
	content, err := metadataFile.Contents()
	if err != nil {
		return nil, fmt.Errorf("read session metadata contents: %w", err)
	}

	var meta CommittedMetadata
	if err := json.Unmarshal([]byte(content), &meta); err != nil {
		return nil, fmt.Errorf("parse session metadata: %w", err)
	}
	return &meta, nil
}

// ReadSessionMetadataAndPrompts reads a session's metadata and prompts from the
// v2 /main ref without requiring the raw transcript from /full/current.
// Used by explain when the raw transcript is unavailable but compact transcript
// (transcript.jsonl) on /main can substitute for display.
// Returns ErrCheckpointNotFound if the checkpoint or session doesn't exist on /main.
func (s *V2GitStore) ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
	sessionTree, err := s.sessionTreeFromMain(ctx, checkpointID, sessionIndex)
	if err != nil {
		if ctxErr := ctx.Err(); ctxErr != nil {
			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
		}
		return nil, ErrCheckpointNotFound
	}

	result := &SessionContent{}
	sessionFT := s.wrapWithFetcher(ctx, sessionTree)

	if metadataFile, fileErr := sessionFT.File(paths.MetadataFileName); fileErr == nil {
		if content, contentErr := metadataFile.Contents(); contentErr == nil {
			if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr != nil {
				return nil, fmt.Errorf("failed to parse session metadata: %w", jsonErr)
			}
		}
	}

	if file, fileErr := sessionFT.File(paths.PromptFileName); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			result.Prompts = content
		}
	}

	// Read compact transcript from the same session tree (avoids a second tree walk).
	if compactFile, fileErr := sessionFT.File(paths.CompactTranscriptFileName); fileErr == nil {
		if content, contentErr := compactFile.Contents(); contentErr == nil && content != "" {
			result.Transcript = []byte(content)
		}
	}

	return result, nil
}

func (s *V2GitStore) ReadSessionPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (string, error) {
	sessionTree, err := s.sessionTreeFromMain(ctx, checkpointID, sessionIndex)
	if err != nil {
		if ctxErr := ctx.Err(); ctxErr != nil {
			return "", ctxErr //nolint:wrapcheck // Propagating context cancellation
		}
		return "", ErrCheckpointNotFound
	}

	sessionFT := s.wrapWithFetcher(ctx, sessionTree)
	file, err := sessionFT.File(paths.PromptFileName)
	if err != nil {
		return "", nil //nolint:nilerr // Missing prompt.txt means no recorded prompts.
	}
	content, err := file.Contents()
	if err != nil {
		return "", nil //nolint:nilerr // Keep committed prompt reads best-effort.
	}
	return content, nil
}

// GetCheckpointAuthor retrieves the author of a checkpoint from the v2 /main
// commit history.
func (s *V2GitStore) GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error) {
	return getCheckpointAuthorFromRef(ctx, s.repo, plumbing.ReferenceName(paths.V2MainRefName), checkpointID)
}

// ReadSessionContent reads a session's metadata and prompts from the v2 /main ref,
// and the raw transcript (raw_transcript) from /full/current.
// This is the v2 equivalent of GitStore.ReadSessionContent — it reads the raw agent
// transcript, not the compact transcript.jsonl. Used by resume and RestoreLogsOnly.
// Returns ErrNoTranscript if the session exists but no raw transcript is available.
// Returns ErrCheckpointNotFound if the checkpoint or session doesn't exist on /main.
func (s *V2GitStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
	sessionTree, err := s.sessionTreeFromMain(ctx, checkpointID, sessionIndex)
	if err != nil {
		return nil, err
	}

	result := &SessionContent{}
	sessionFT := s.wrapWithFetcher(ctx, sessionTree)

	if metadataFile, fileErr := sessionFT.File(paths.MetadataFileName); fileErr == nil {
		if content, contentErr := metadataFile.Contents(); contentErr == nil {
			if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr != nil {
				return nil, fmt.Errorf("failed to parse session metadata: %w", jsonErr)
			}
		}
	}

	if file, fileErr := sessionFT.File(paths.PromptFileName); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			result.Prompts = content
		}
	}

	transcript, transcriptErr := s.readTranscriptFromFullRefs(ctx, checkpointID, sessionIndex, result.Metadata.Agent)
	if transcriptErr != nil {
		return nil, fmt.Errorf("failed to read transcript from /full refs: %w", transcriptErr)
	}
	if len(transcript) == 0 {
		return nil, ErrNoTranscript
	}
	result.Transcript = transcript

	return result, nil
}

func (s *V2GitStore) sessionTreeFromMain(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*object.Tree, error) {
	if err := ctx.Err(); err != nil {
		return nil, err //nolint:wrapcheck // Propagating context cancellation
	}

	refName := plumbing.ReferenceName(paths.V2MainRefName)
	_, rootTreeHash, err := s.GetRefState(refName)
	if err != nil {
		return nil, ErrCheckpointNotFound
	}

	rootTree, err := s.repo.TreeObject(rootTreeHash)
	if err != nil {
		return nil, ErrCheckpointNotFound
	}

	cpTree, err := rootTree.Tree(checkpointID.Path())
	if err != nil {
		return nil, ErrCheckpointNotFound
	}

	sessionDir := strconv.Itoa(sessionIndex)
	sessionTree, err := cpTree.Tree(sessionDir)
	if err != nil {
		return nil, fmt.Errorf("session %d not found: %w", sessionIndex, err)
	}

	return sessionTree, nil
}

// readTranscriptFromFullRefs reads the raw transcript for a checkpoint session
// by searching /full/current first, then archived generations in reverse order.
// If not found locally, it discovers and fetches remote /full/* refs.
func (s *V2GitStore) readTranscriptFromFullRefs(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int, agentType types.AgentType) ([]byte, error) {
	if err := ctx.Err(); err != nil {
		return nil, err //nolint:wrapcheck // Propagating context cancellation
	}

	sessionPath := fmt.Sprintf("%s/%d", checkpointID.Path(), sessionIndex)

	// Search locally first.
	transcript, err := s.readTranscriptFromRef(plumbing.ReferenceName(paths.V2FullCurrentRefName), sessionPath, agentType)
	if err == nil && len(transcript) > 0 {
		return transcript, nil
	}

	archived, err := s.listArchivedFullRefs()
	if err != nil {
		return nil, err
	}
	for i := len(archived) - 1; i >= 0; i-- {
		transcript, err := s.readTranscriptFromRef(archived[i], sessionPath, agentType)
		if err == nil && len(transcript) > 0 {
			return transcript, nil
		}
	}

	if fetchErr := s.fetchRemoteFullRefs(ctx); fetchErr != nil {
		logging.Debug(ctx, "failed to fetch remote /full/* refs",
			slog.String("error", fetchErr.Error()),
		)
		return nil, nil
	}

	// Search again after fetching. Current is force-fetched so a stale or empty
	// local /full/current can recover, while archived refs are fetched only when
	// absent locally.
	transcript, err = s.readTranscriptFromRef(plumbing.ReferenceName(paths.V2FullCurrentRefName), sessionPath, agentType)
	if err == nil && len(transcript) > 0 {
		return transcript, nil
	}

	// Skip refs already scanned pre-fetch. Use a membership set rather than a
	// length boundary: archive ref names can interleave in lex order across
	// machines (clocks diverge per the fetchRemoteFullRefs comment), so a new
	// ref may sort before existing local ones.
	checkedArchived := make(map[plumbing.ReferenceName]struct{}, len(archived))
	for _, ref := range archived {
		checkedArchived[ref] = struct{}{}
	}
	archived, err = s.listArchivedFullRefs()
	if err != nil {
		return nil, nil //nolint:nilerr // Best-effort: fetch-on-demand failure shouldn't block resume.
	}
	for i := len(archived) - 1; i >= 0; i-- {
		ref := archived[i]
		if _, checked := checkedArchived[ref]; checked {
			continue
		}
		transcript, err := s.readTranscriptFromRef(ref, sessionPath, agentType)
		if err == nil && len(transcript) > 0 {
			return transcript, nil
		}
	}

	return nil, nil
}

func (s *V2GitStore) listArchivedFullRefs() ([]plumbing.ReferenceName, error) {
	refs, err := s.repo.References()
	if err != nil {
		return nil, fmt.Errorf("failed to list references: %w", err)
	}

	prefix := v2FullRefPrefix()
	var archived []string
	err = refs.ForEach(func(ref *plumbing.Reference) error {
		name := ref.Name().String()
		if !strings.HasPrefix(name, prefix) {
			return nil
		}
		suffix := strings.TrimPrefix(name, prefix)
		if !isV2ArchivedFullRefSuffix(suffix) {
			return nil
		}
		archived = append(archived, name)
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("failed to iterate references: %w", err)
	}

	sort.Strings(archived)
	result := make([]plumbing.ReferenceName, 0, len(archived))
	for _, ref := range archived {
		result = append(result, plumbing.ReferenceName(ref))
	}
	return result, nil
}

// fetchRemoteFullRefs discovers and fetches v2 /full/* refs from the effective
// checkpoint fetch target. /full/current is force-fetched; archived generation
// refs are fetched only when absent locally because old archives should be
// immutable but may have diverged across machines.
func (s *V2GitStore) fetchRemoteFullRefs(ctx context.Context) error {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()

	repoRoot, _, err := s.gs.repoDirs(ctx)
	if err != nil {
		return err
	}

	fetchTarget := v2FullRefsFetchTarget(ctx, repoRoot)
	output, err := remote.LsRemoteInDir(ctx, repoRoot, fetchTarget, v2FullRefPrefix()+"*")
	if err != nil {
		return fmt.Errorf("ls-remote failed: %w", err)
	}

	var refSpecs []string
	for line := range strings.SplitSeq(strings.TrimSpace(string(output)), "\n") {
		if line == "" {
			continue
		}
		parts := strings.Fields(line)
		if len(parts) < 2 {
			continue
		}
		remoteRefName := parts[1]
		if !isV2FetchableFullRef(remoteRefName) {
			continue
		}

		if remoteRefName != paths.V2FullCurrentRefName {
			if _, refErr := s.repo.Reference(plumbing.ReferenceName(remoteRefName), true); refErr == nil {
				continue
			}
		}

		refSpecs = append(refSpecs, fmt.Sprintf("+%s:%s", remoteRefName, remoteRefName))
	}

	if len(refSpecs) == 0 {
		return nil
	}

	if fetchOutput, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
		Remote:   fetchTarget,
		RefSpecs: refSpecs,
		NoTags:   true,
		NoFilter: true,
		Dir:      repoRoot,
	}); fetchErr != nil {
		if output := strings.TrimSpace(string(fetchOutput)); output != "" {
			return fmt.Errorf("fetch failed: %s: %w", output, fetchErr)
		}
		return fmt.Errorf("fetch failed: %w", fetchErr)
	}

	return nil
}

func v2FullRefsFetchTarget(ctx context.Context, repoRoot string) string {
	target, err := remote.FetchURL(ctx, remote.FetchURLOptions{WorktreeRoot: repoRoot})
	if err == nil && target != "" {
		return target
	}
	return "origin"
}

func v2FullRefPrefix() string {
	return strings.TrimSuffix(paths.V2FullCurrentRefName, "current")
}

func isV2FetchableFullRef(refName string) bool {
	if refName == paths.V2FullCurrentRefName {
		return true
	}
	if !strings.HasPrefix(refName, v2FullRefPrefix()) {
		return false
	}
	return isV2ArchivedFullRefSuffix(strings.TrimPrefix(refName, v2FullRefPrefix()))
}

func isV2ArchivedFullRefSuffix(suffix string) bool {
	if len(suffix) != 13 {
		return false
	}
	for _, r := range suffix {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

// readTranscriptFromRef reads the raw transcript from a specific /full/* ref.
// Follows the same chunking convention as readTranscriptFromTree in committed.go:
// chunk 0 is the base file (raw_transcript), chunks 1+ are raw_transcript.001, .002, etc.
// When chunk files exist, all chunks (including chunk 0) are reassembled using
// agent-aware reassembly via agent.ReassembleTranscript.
func (s *V2GitStore) readTranscriptFromRef(refName plumbing.ReferenceName, sessionPath string, agentType types.AgentType) ([]byte, error) {
	_, rootTreeHash, err := s.GetRefState(refName)
	if err != nil {
		return nil, err
	}

	rootTree, err := s.repo.TreeObject(rootTreeHash)
	if err != nil {
		return nil, fmt.Errorf("failed to read tree: %w", err)
	}

	sessionTree, err := rootTree.Tree(sessionPath)
	if err != nil {
		return nil, fmt.Errorf("session path %s not found: %w", sessionPath, err)
	}

	return readTranscriptFromObjectTree(sessionTree, agentType)
}

// readTranscriptFromObjectTree reads and reassembles a transcript from a git tree object.
// Handles both chunked and non-chunked transcripts. Uses agent-aware reassembly
// when agentType is known, falling back to JSONL reassembly otherwise.
func readTranscriptFromObjectTree(tree *object.Tree, agentType types.AgentType) ([]byte, error) {
	var chunkFiles []string
	var hasBaseFile bool

	for _, entry := range tree.Entries {
		if entry.Name == paths.V2RawTranscriptFileName {
			hasBaseFile = true
		}
		if strings.HasPrefix(entry.Name, paths.V2RawTranscriptFileName+".") {
			idx := agent.ParseChunkIndex(entry.Name, paths.V2RawTranscriptFileName)
			if idx > 0 {
				chunkFiles = append(chunkFiles, entry.Name)
			}
		}
	}

	// If chunk files exist, reassemble all chunks (base file is chunk 0)
	if len(chunkFiles) > 0 {
		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.V2RawTranscriptFileName)
		if hasBaseFile {
			chunkFiles = append([]string{paths.V2RawTranscriptFileName}, chunkFiles...)
		}

		var chunks [][]byte
		for _, chunkFile := range chunkFiles {
			file, fileErr := tree.File(chunkFile)
			if fileErr != nil {
				continue
			}
			content, contentErr := file.Contents()
			if contentErr != nil {
				continue
			}
			chunks = append(chunks, []byte(content))
		}

		if len(chunks) > 0 {
			result, reassembleErr := agent.ReassembleTranscript(chunks, agentType)
			if reassembleErr != nil {
				return nil, fmt.Errorf("failed to reassemble transcript: %w", reassembleErr)
			}
			return result, nil
		}
	}

	// No chunk files — read base file directly (non-chunked transcript)
	if hasBaseFile {
		file, err := tree.File(paths.V2RawTranscriptFileName)
		if err == nil {
			content, contentErr := file.Contents()
			if contentErr == nil {
				return []byte(content), nil
			}
		}
	}

	return nil, nil
}

// ReadSessionContentByID finds the session with the given sessionID in a checkpoint
// and returns its content. Mirrors GitStore.ReadSessionContentByID for v2 refs.
// Returns ErrCheckpointNotFound if the checkpoint doesn't exist; returns a
// non-wrapped error (containing the session ID and checkpoint ID for context)
// if no session in the checkpoint matches sessionID.
func (s *V2GitStore) ReadSessionContentByID(ctx context.Context, checkpointID id.CheckpointID, sessionID string) (*SessionContent, error) {
	summary, err := s.ReadCommitted(ctx, checkpointID)
	if err != nil {
		return nil, err
	}
	if summary == nil {
		return nil, ErrCheckpointNotFound
	}

	for i := range summary.Sessions {
		content, readErr := s.ReadSessionContent(ctx, checkpointID, i)
		if readErr != nil {
			continue
		}
		if content != nil && content.Metadata.SessionID == sessionID {
			return content, nil
		}
	}

	return nil, fmt.Errorf("session %q not found in checkpoint %s", sessionID, checkpointID)
}

// GetSessionLog reads the latest session's raw transcript and session ID from v2 refs.
// Convenience wrapper matching the GitStore.GetSessionLog signature.
func (s *V2GitStore) GetSessionLog(ctx context.Context, cpID id.CheckpointID) ([]byte, string, error) {
	summary, err := s.ReadCommitted(ctx, cpID)
	if err != nil {
		return nil, "", err
	}
	if summary == nil {
		return nil, "", ErrCheckpointNotFound
	}
	if len(summary.Sessions) == 0 {
		return nil, "", ErrCheckpointNotFound
	}

	latestIndex := len(summary.Sessions) - 1
	content, err := s.ReadSessionContent(ctx, cpID, latestIndex)
	if err != nil {
		return nil, "", err
	}
	return content.Transcript, content.Metadata.SessionID, nil
}

package checkpoint

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os/exec"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/logging"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// V2GitStore provides read operations for the v2 ref layout.
// It reads from two custom refs under refs/entire/:
//   - /main: permanent metadata + compact transcripts
//   - /full/current: raw transcripts
//
// V2GitStore is separate from GitStore (v1) to keep concerns isolated
// and simplify future v1 removal.
type V2GitStore struct {
	repo *git.Repository
	gs   *GitStore // shared entry-building helpers (same package)

	// blobFetcher fetches missing blobs by hash. When set, read paths wrap
	// trees with FetchingTree so missing blobs are auto-recovered (and the
	// cat-file fallback covers partial-clone-filtered blobs that go-git's
	// storer can't see).
	blobFetcher BlobFetchFunc
}

// NewV2GitStore creates a new v2 checkpoint store backed by the given git repository.
func NewV2GitStore(repo *git.Repository) *V2GitStore {
	return &V2GitStore{
		repo: repo,
		gs:   &GitStore{repo: repo},
	}
}

// SetBlobFetcher configures the store to automatically fetch missing blobs
// on demand when reading from /main trees. Mirrors GitStore.SetBlobFetcher.
// Required for reads against partial-clone repos where blobs may be absent
// or invisible to go-git's cached packfile index.
func (s *V2GitStore) SetBlobFetcher(f BlobFetchFunc) {
	s.blobFetcher = f
}

// wrapWithFetcher returns the input tree wrapped in a FetchingTree using
// the configured blob fetcher. Callers use the returned tree's File() /
// Tree() methods instead of the raw go-git ones so missing blobs are
// recovered via the fetcher and the cat-file fallback.
func (s *V2GitStore) wrapWithFetcher(ctx context.Context, tree *object.Tree) *FetchingTree {
	return NewFetchingTree(ctx, tree, s.repo.Storer, s.blobFetcher)
}

// GetRefState returns the parent commit hash and root tree hash for a ref.
// Falls back to `git rev-parse <hash>^{tree}` when go-git can't load the
// commit object — same partial-clone / stale-packfile-cache reason as
// readTreeEntriesViaCLI in parse_tree.go.
func (s *V2GitStore) GetRefState(refName plumbing.ReferenceName) (parentHash, treeHash plumbing.Hash, err error) {
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("ref %s not found: %w", refName, err)
	}

	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		cliTreeHash, cliErr := commitTreeHashViaCLI(context.Background(), ref.Hash())
		if cliErr != nil {
			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit for ref %s: %w", refName, errors.Join(err, cliErr))
		}
		logging.Warn(context.Background(), "GetRefState: go-git commit read failed, used git rev-parse fallback",
			slog.String("ref", refName.String()),
			slog.String("commit", ref.Hash().String()[:12]),
			slog.String("gogit_error", err.Error()),
		)
		return ref.Hash(), cliTreeHash, nil
	}

	return ref.Hash(), commit.TreeHash, nil
}

// commitTreeHashViaCLI resolves the tree hash of a commit via
// `git rev-parse <hash>^{tree}`. See GetRefState for the rationale.
func commitTreeHashViaCLI(ctx context.Context, commitHash plumbing.Hash) (plumbing.Hash, error) {
	cmd := exec.CommandContext(ctx, "git", "rev-parse", commitHash.String()+"^{tree}")
	output, err := cmd.Output()
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("git rev-parse %s^{tree}: %w", commitHash.String()[:12], err)
	}
	hex := strings.TrimSpace(string(output))
	if hex == "" {
		return plumbing.ZeroHash, fmt.Errorf("git rev-parse %s^{tree}: empty output", commitHash.String()[:12])
	}
	return plumbing.NewHash(hex), nil
}

package checkpoint

import (
	"context"
	"errors"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/paths"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// FetchRefFunc is a function that fetches a ref from the remote.
// Used as a dependency injection point so this package doesn't import cli.
type FetchRefFunc func(ctx context.Context) error

// GetV2MetadataTree resolves the v2 /main ref tree with fetch fallback.
// Fallback order:
//  1. Treeless fetch → open fresh repo → read /main ref tree
//  2. Full fetch when the treeless refresh did not produce a readable tree
//  3. Local ref lookup
//  4. Full fetch when no treeless refresh was attempted
//
// Takes fetch functions as dependencies to avoid importing the cli package.
// openRepoFn opens a fresh repository (needed after fetch to see new packfiles).
func GetV2MetadataTree(ctx context.Context, treelessFetchFn, fullFetchFn FetchRefFunc, openRepoFn func(context.Context) (*git.Repository, error)) (*object.Tree, *git.Repository, error) {
	refName := plumbing.ReferenceName(paths.V2MainRefName)
	fullFetchTried := false

	tryFullFetch := func() (*object.Tree, *git.Repository, bool) {
		if fullFetchFn == nil || fullFetchTried {
			return nil, nil, false
		}
		fullFetchTried = true
		if fetchErr := fullFetchFn(ctx); fetchErr != nil {
			return nil, nil, false
		}
		freshRepo, repoErr := openRepoFn(ctx)
		if repoErr != nil {
			return nil, nil, false
		}
		tree, treeErr := getV2RefTree(freshRepo, refName)
		if treeErr != nil {
			_ = freshRepo.Close()
			return nil, nil, false
		}
		return tree, freshRepo, true
	}

	if treelessFetchFn != nil {
		if fetchErr := treelessFetchFn(ctx); fetchErr == nil {
			freshRepo, repoErr := openRepoFn(ctx)
			if repoErr == nil {
				tree, treeErr := getV2RefTree(freshRepo, refName)
				if treeErr == nil {
					return tree, freshRepo, nil
				}
				_ = freshRepo.Close()
			}
		}
		if tree, repo, ok := tryFullFetch(); ok {
			return tree, repo, nil
		}
	}

	localRepo, repoErr := openRepoFn(ctx)
	if repoErr == nil {
		tree, err := getV2RefTree(localRepo, refName)
		if err == nil {
			return tree, localRepo, nil
		}
		_ = localRepo.Close()
	}

	if tree, repo, ok := tryFullFetch(); ok {
		return tree, repo, nil
	}

	return nil, nil, errors.New("v2 /main ref not available")
}

// getV2RefTree reads the tree from a custom ref (not a branch — no refs/heads/ prefix).
func getV2RefTree(repo *git.Repository, refName plumbing.ReferenceName) (*object.Tree, error) {
	ref, err := repo.Reference(refName, true)
	if err != nil {
		return nil, fmt.Errorf("ref %s not found: %w", refName, err)
	}

	commit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get commit for ref %s: %w", refName, err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("failed to get tree for ref %s: %w", refName, err)
	}
	return tree, nil
}

package checkpoint

import (
	"context"
	"errors"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/redact"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/go-git/go-git/v6"
)

func TestGetV2MetadataTree_LocalRef(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	cpID := id.MustCheckpointID("a1a2a3a4a5a6")
	ctx := context.Background()

	// Write a checkpoint fixture so the /main ref exists.
	writeV2TestCheckpoint(t, repo, v2TestCheckpointOptions{
		CheckpointID: cpID,
		SessionID:    "session-1",
		Strategy:     "manual-commit",
		Transcript:   redact.AlreadyRedacted([]byte(`{"test": true}`)),
	})

	openRepoFn := func(_ context.Context) (*git.Repository, error) {
		return repo, nil
	}

	// nil fetch functions — only local ref lookup should be tried
	tree, returnedRepo, err := GetV2MetadataTree(ctx, nil, nil, openRepoFn)
	require.NoError(t, err)
	require.NotNil(t, tree)
	assert.Equal(t, repo, returnedRepo)

	// Verify the tree contains the checkpoint subtree
	cpTree, err := tree.Tree(cpID.Path())
	require.NoError(t, err)
	require.NotNil(t, cpTree)
}

func TestGetV2MetadataTree_NoRef_ReturnsError(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	ctx := context.Background()

	openRepoFn := func(_ context.Context) (*git.Repository, error) {
		return repo, nil
	}

	// No v2 ref exists, no fetch functions — should fail
	tree, _, err := GetV2MetadataTree(ctx, nil, nil, openRepoFn)
	require.Error(t, err)
	assert.Nil(t, tree)
}

func TestGetV2MetadataTree_FetchSucceeds(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	cpID := id.MustCheckpointID("b1b2b3b4b5b6")
	ctx := context.Background()

	// Write checkpoint fixture so the ref exists after "fetch".
	writeV2TestCheckpoint(t, repo, v2TestCheckpointOptions{
		CheckpointID: cpID,
		SessionID:    "session-1",
		Strategy:     "manual-commit",
		Transcript:   redact.AlreadyRedacted([]byte(`{"test": true}`)),
	})

	fetchCalled := false
	treelessFetchFn := func(_ context.Context) error {
		fetchCalled = true
		return nil // Simulate successful fetch
	}

	openRepoFn := func(_ context.Context) (*git.Repository, error) {
		return repo, nil
	}

	tree, _, err := GetV2MetadataTree(ctx, treelessFetchFn, nil, openRepoFn)
	require.NoError(t, err)
	require.NotNil(t, tree)
	assert.True(t, fetchCalled, "treeless fetch should have been called")
}

func TestGetV2MetadataTree_TreelessFetchFails_FallsBackToFullFetch(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	cpID := id.MustCheckpointID("c1c2c3c4c5c6")
	ctx := context.Background()

	writeV2TestCheckpoint(t, repo, v2TestCheckpointOptions{
		CheckpointID: cpID,
		SessionID:    "session-1",
		Strategy:     "manual-commit",
		Transcript:   redact.AlreadyRedacted([]byte(`{"test": true}`)),
	})

	treelessFetchFn := func(_ context.Context) error {
		return errors.New("treeless fetch failed")
	}
	fullFetchCalled := false
	fullFetchFn := func(_ context.Context) error {
		fullFetchCalled = true
		return nil
	}

	openRepoFn := func(_ context.Context) (*git.Repository, error) {
		return repo, nil
	}

	tree, _, err := GetV2MetadataTree(ctx, treelessFetchFn, fullFetchFn, openRepoFn)
	require.NoError(t, err)
	require.NotNil(t, tree)
	assert.True(t, fullFetchCalled, "full fetch should be tried before accepting a stale local ref")
}

